insert into public.site_settings(id,value) values('site','{"heroTitle":"Damit mehr Zeit für dich bleibt.","heroSubtitle":"Gedanken festhalten. Aufgaben ordnen. Den Alltag leichter machen. Entdecke Sproutly, deinen persönlichen KI-Assistenten.","apple":"","google":"","instagram":"https://www.instagram.com/sproutly.ch/","facebook":"https://www.facebook.com/profile.php?id=61595130966995","tiktok":"https://www.tiktok.com/@sproutly.ch","instagramPost":"","analyticsEnabled":false,"company":"","address":"","contact":"","legalVerified":false,"feedbackRetentionDays":180,"contactRetentionDays":90,"logRetentionDays":90,"seoTitle":"Sproutly – Damit mehr Zeit für dich bleibt","seoDescription":"Entdecke Sproutly: dein persönlicher KI-Assistent für Aufgaben, Notizen und Projekte. Neuigkeiten, Roadmap und Feedback an einem Ort.","indexable":false}'::jsonb) on conflict do nothing;
insert into public.feature_cards(title,description,status,position,visible,locale,data,published_at) values('Ein Gedanke. Ein Anfang.','Halte fest, was dich beschäftigt – mit deinem persönlichen KI-Assistenten.','published',0,true,'de','{"icon":"sparkles","media":"/images/assistants.png","alt":"KI-Assistenten in einer früheren Sproutly-Version"}'::jsonb,now());
insert into public.feature_cards(title,description,status,position,visible,locale,data,published_at) values('Weniger im Kopf. Mehr im Blick.','Aufgaben und Projekte bekommen ihren Platz. Damit du dich auf das Wesentliche konzentrieren kannst.','published',1,true,'de','{"icon":"check"}'::jsonb,now());
insert into public.feature_cards(title,description,status,position,visible,locale,data,published_at) values('Gute Gedanken bleiben.','Notizen sammeln und Informationen wiederfinden. An einem Ort, der zu deinem Alltag gehört.','published',2,true,'de','{"icon":"notes","media":"/images/notes.png","alt":"Notizansicht einer früheren Sproutly-Version"}'::jsonb,now());
insert into public.faqs(title,description,status,position,visible,locale,data,published_at) values('Was ist Sproutly?','Sproutly ist eine persönliche KI-Assistenten-App für die Organisation von Aufgaben, Notizen und Projekten.','published',0,true,'de','{}'::jsonb,now());
insert into public.faqs(title,description,status,position,visible,locale,data,published_at) values('Wo kann ich Sproutly herunterladen?','Die offiziellen Store-Links sind noch nicht hinterlegt. Sobald sie bestätigt sind, findest du sie auf unserer Download-Seite.','published',1,true,'de','{}'::jsonb,now());
insert into public.faqs(title,description,status,position,visible,locale,data,published_at) values('Was kostet Sproutly?','Die verbindlichen Preise werden zum Start bekannt gegeben. Aktuell veröffentlichen wir noch keine Preisangaben.','published',2,true,'de','{}'::jsonb,now());
insert into public.faqs(title,description,status,position,visible,locale,data,published_at) values('Wo kann ich meine Ideen teilen?','Im Developer Hub kannst du Funktionen vorschlagen, Fragen stellen und Fehler melden. Beiträge werden vor einer Veröffentlichung geprüft.','published',3,true,'de','{}'::jsonb,now());
